Section CANSEC1. Context {rc : runConstT}.

Section P1.
  Variables (SPV SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (mb : amem) (DT W FF mtl lo : Z) (h : hstats) (maxW : Z) (rs0a : list Z) (nz : Z) (rs0d : list Z)
            (sorted : list (option Z)) (rv0 rv : list Z) (cells : list (option deltX2)) (jdt SYj : list byte).
  Variable Q : machine_state -> Prop.
  Notation tl := (hs_tableLog h).
  Notation T := (x2T (hs_tableLog h) mtl).
  Notation rs0 := (Zupd (0 + 1) 0 rs0d).
  Notation mB := (hs_tableLog h + 1 - maxW).
  Notation ncells := (Z.to_nat (2 ^ mtl)).
  Notation WB := (x2WB SPA DT W mtl).
  Hypothesis XP : X2PATH mtl h maxW rs0a nz rs0d sorted rv0 rv cells.
  Hypothesis HMTL : 1 <= mtl <= 12.
  Hypothesis HDT : ablk DT (DT + 4 + 4 * 2 ^ mtl).
  Hypothesis DT8 : DT mod 8 = 0.
  Hypothesis HWK : ablk W (W + 8704).
  Hypothesis DJW : DT + 4 + 4 * 2 ^ mtl <= W \/ W + 8704 <= DT.
  Hypothesis DSP : DT + 4 + 4 * 2 ^ mtl <= SPA.
  Hypothesis WSP : W + 8704 <= SPA.
  Hypothesis KSP : KHIGH <= SPA.
  Hypothesis SP47 : SPA + 832 <= 2^47.
  Hypothesis UDT : unpoisoned mb DT (DT + 4 + 4 * 2 ^ mtl).
  Hypothesis ZW : zshadow mb W 8704.
  Hypothesis ZDT : zshadow mb DT 8.
  Hypothesis RDT : rng RNG DT (4 + 4 * 2 ^ mtl).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 4 * 2 ^ mtl + DT mod 8)).
  Hypothesis RWK : rng RNG W 8704.
  Hypothesis RWKs : rng RNG (shad W) (nshad (8704 + W mod 8)).
  Hypothesis RFR : rng RNG SPA 832.
  Hypothesis LJD : length jdt = Z.to_nat (4 * 2 ^ mtl).
  Hypothesis LSY : length SYj = 256%nat.
  Hypothesis BOT : ATOP + 4096 <= lo.
  Hypothesis LOS : lo <= SPA.
  Hypothesis FC : FF + 64 <= ATOP.
  Hypothesis FFW : FF + 64 <= W \/ W + 8704 <= FF.
  Hypothesis RNS : rng RNG (FF + 48) 4.
  Hypothesis KFIN : x2kfin SPV SPA gp tp F fc RNG mb DT W FF mtl lo T (hs_ret h) jdt cells Q.


  Notation WP := [(SPA + 16, SPA + 32); (SPA + 48, SPA + 56); (SPA + 80, SPA + 88); (SPA + 256, SPA + 264);
