  Notation ws := (hs_weights h).
  Notation nbS := (hs_nbSymbols h).

  (* [comment removed for export] *)
  Definition x2pk1 (m : amem) : Prop :=
    (exists q32 q40, rw_cells asegs m (SPA + 32) [C8 q32; C8 q40]) /\ (exists j, rw_cells asegs m (SPA + 88) [CB 8 j])
    /\ rw_cells asegs m (SPA + 96) [C8 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))]
    /\ (exists v, rw_cells asegs m (SPA + 104) [C8 v]) /\ (exists v, rw_cells asegs m (SPA + 144) [C8 v])
    /\ (exists j, rw_cells asegs m (SPA + 152) [CB 8 j]) /\ (exists v, rw_cells asegs m (SPA + 160) [C8 v])
    /\ (exists j, rw_cells asegs m (SPA + 168) [CB 24 j])
    /\ (exists q192 q200 q208 q216 q224 q232 q240 q248,
          rw_cells asegs m (SPA + 192) [C8 q192; C8 q200; C8 q208; C8 q216; C8 q224; C8 q232; C8 q240; C8 q248])
    /\ (exists j, rw_cells asegs m (SPA + 264) [CB 24 j]) /\ (exists j, rw_cells asegs m (SPA + 288) [CB 8 j])
    /\ (exists j, rw_cells asegs m (SPA + 296) [CB 272 j]) /\ (exists j, rw_cells asegs m (SPA + 568) [CB 16 j])
    /\ (exists j, rw_cells asegs m (SPA + 616) [CB 8 j]) /\ (exists j, rw_cells asegs m (SPA + 624) [CB 80 j])
    /\ u8arr asegs m DT (le4 (Z_to_bv 64 (mtl * 16777217))) /\ u8arr asegs m (DT + 4) jdt
    /\ (exists RVj, length RVj = 624%nat /\ u8arr asegs m W RVj).

  Lemma x2pk1_transport : forall m m', x2pk1 m -> munch WP m m' -> wmono asegs m m' -> x2pk1 m'.
